package com.chatfont;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("chatfont")
public interface ChatFontConfig extends Config
{
	@ConfigItem(
		keyName = "chatboxFont",
		name = "Chatbox font",
		description = "Font used for chat messages",
		position = 1
	)
	default GameFont chatboxFont()
	{
		return GameFont.DEFAULT;
	}

	@ConfigItem(
		keyName = "dialogueFont",
		name = "Dialogue font",
		description = "Font used for NPC/player dialogue and dialogue options",
		position = 2
	)
	default GameFont dialogueFont()
	{
		return GameFont.DEFAULT;
	}

	@ConfigItem(
		keyName = "questFont",
		name = "Quest journal font",
		description = "Font used in the quest journal",
		position = 3
	)
	default GameFont questFont()
	{
		return GameFont.DEFAULT;
	}
}

package com.chatfont;

import com.google.inject.Provides;
import java.util.Map;
import java.util.WeakHashMap;
import java.util.function.Consumer;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.FontID;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@Slf4j
@PluginDescriptor(
	name = "Chat Font",
	description = "Change the font of the chatbox, dialogue and quest journal",
	tags = {"font", "chat", "dialogue", "quest", "text"}
)
public class ChatFontPlugin extends Plugin
{
	// NPC dialogue, player dialogue, options, item/sprite dialogues, message boxes
	private static final int[] DIALOGUE_GROUPS = {
		InterfaceID.CHAT_LEFT, InterfaceID.CHAT_RIGHT, InterfaceID.CHATMENU,
		InterfaceID.OBJECTBOX, InterfaceID.OBJECTBOX_DOUBLE, InterfaceID.MESSAGEBOX
	};
	private static final int[] QUEST_JOURNAL_GROUPS = {InterfaceID.QUESTJOURNAL};
	private static final int CHAT_DEFAULT_FONT = FontID.PLAIN_12;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ChatFontConfig config;

	// The font we last applied to the chatbox, so we can switch or undo it
	private int appliedChatFont = -1;

	// Original fonts of dialogue/quest widgets we've changed, so they can be put back.
	// Weak keys so widgets from closed interfaces are dropped
	private final Map<Widget, Integer> dialogueOriginals = new WeakHashMap<>();
	private final Map<Widget, Integer> questOriginals = new WeakHashMap<>();

	@Override
	protected void shutDown()
	{
		clientThread.invoke(() ->
		{
			resetChatbox();
			restore(dialogueOriginals);
			restore(questOriginals);
		});
	}

	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		applyChatbox();

		applyGroups(DIALOGUE_GROUPS, config.dialogueFont().getFontId(), dialogueOriginals);
		applyGroups(QUEST_JOURNAL_GROUPS, config.questFont().getFontId(), questOriginals);
	}

	private void applyGroups(int[] groups, int fontId, Map<Widget, Integer> originals)
	{
		if (fontId == -1)
		{
			restore(originals);
			return;
		}

		for (int group : groups)
		{
			forEachTextWidget(group, w ->
			{
				originals.putIfAbsent(w, w.getFontId());
				setFont(w, fontId);
			});
		}
	}

	private void restore(Map<Widget, Integer> originals)
	{
		originals.forEach(this::setFont);
		originals.clear();
	}

	private void applyChatbox()
	{
		int target = config.chatboxFont().getFontId();
		if (target == -1)
		{
			if (appliedChatFont != -1)
			{
				resetChatbox();
			}
			return;
		}

		final int previous = appliedChatFont;
		forEachTextWidget(InterfaceID.CHATBOX, w ->
		{
			int font = w.getFontId();
			// Only touch text using the normal chat font (or our previous choice),
			// so tabs and other labels keep their own fonts
			if (font == CHAT_DEFAULT_FONT || (previous != -1 && font == previous))
			{
				setFont(w, target);
			}
		});
		appliedChatFont = target;
	}

	private void resetChatbox()
	{
		if (appliedChatFont == -1)
		{
			return;
		}
		final int previous = appliedChatFont;
		forEachTextWidget(InterfaceID.CHATBOX, w ->
		{
			if (w.getFontId() == previous)
			{
				w.setFontId(CHAT_DEFAULT_FONT);
			}
		});
		appliedChatFont = -1;
	}

	private void setFont(Widget w, int fontId)
	{
		if (w.getFontId() != fontId)
		{
			w.setFontId(fontId);
		}
	}

	private void forEachTextWidget(int groupId, Consumer<Widget> action)
	{
		for (int child = 0; ; child++)
		{
			Widget w = client.getWidget(groupId, child);
			if (w == null)
			{
				break;
			}
			visit(w, action);
		}
	}

	private void visit(Widget w, Consumer<Widget> action)
	{
		if (w.getType() == WidgetType.TEXT)
		{
			action.accept(w);
		}
		Widget[] dynamic = w.getDynamicChildren();
		if (dynamic != null)
		{
			for (Widget c : dynamic)
			{
				if (c != null)
				{
					visit(c, action);
				}
			}
		}
	}

	@Provides
	ChatFontConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ChatFontConfig.class);
	}
}

package com.chatfont;

import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.api.FontID;

@Getter
@RequiredArgsConstructor
public enum GameFont
{
	DEFAULT("Game default", -1),
	PLAIN("Plain", FontID.PLAIN_12),
	BOLD("Bold", FontID.BOLD_12),
	QUILL("Quill", FontID.QUILL_MEDIUM),
	VERDANA("Verdana", FontID.VERDANA_13),
	VERDANA_BOLD("Verdana bold", FontID.VERDANA_13_BOLD),
	TAHOMA("Tahoma", FontID.TAHOMA_11),
	FAIRY("Fairy", FontID.FAIRY_SMALL),
	BARBARIAN("Barbarian", FontID.BARBARIAN),
	SUROK("Surok", FontID.SUROK);

	private final String displayName;
	/**
	 * The font id, or -1 to leave the game's font alone
	 */
	private final int fontId;

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.chatfont;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class ChatFontPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(ChatFontPlugin.class);
		RuneLite.main(args);
	}
}
